S = [('Skalare und Vektoren', [('Teil 2: *Vorlesung 2 – Vektoren*', 'Willkommen zu Teil zwei. Jetzt geht es um Vektoren, das wichtigste Werkzeug für alles, was eine Richtung hat.'), ('Skalar: *nur eine Zahl* – Masse, Temperatur, Zeit, Arbeit …', 'Zur Erinnerung: Ein Skalar ist nur eine Zahl mit Einheit. Beispiele sind Masse, Temperatur, Zeit und auch die Arbeit.'), ('Vektor: Zahl *und Richtung* – Weg, Geschwindigkeit, Kraft …', 'Ein Vektor hat zusätzlich eine Richtung. Beispiele sind Weg, Geschwindigkeit, Beschleunigung und Kraft. Für dich als Bauingenieur ist die Kraft der wichtigste Vektor.')]), ('Wann sind Vektoren gleich?', [('Pfeil von *Anfangspunkt A* zu *Endpunkt E*', 'Ein Vektor ist ein Pfeil vom Anfangspunkt A zum Endpunkt E. Seine Länge ist der Betrag, seine Richtung zeigt die Pfeilspitze.'), ('Gleich, wenn *Betrag und Richtung* übereinstimmen', 'Zwei Vektoren sind gleich, wenn Betrag und Richtung übereinstimmen. Wo der Pfeil anfängt, ist egal. Die beiden Pfeile in der Mitte sind also derselbe Vektor.'), ('−a: *gleich lang*, aber *entgegengesetzt*', 'Rechts siehst du a und minus a: gleich lang, aber genau entgegengesetzt.'), ('Verschieben erlaubt → *freie Vektoren*', 'Weil man diese Pfeile beliebig parallel verschieben darf, nennt man sie freie Vektoren.')]), ('Parallel und antiparallel', [('*Parallel* ↑↑: gleiche Richtung (Länge egal)', 'Zeigen zwei Vektoren in dieselbe Richtung, heißen sie parallel. Ihre Länge darf verschieden sein.'), ('*Antiparallel* ↑↓: entgegengesetzte Richtung', 'Zeigen sie genau entgegengesetzt, heißen sie antiparallel. Das brauchst du gleich beim Skalarprodukt wieder.')]), ('Vektoren addieren', [('A + B: *Anfang von B an die Spitze von A* setzen', 'Jetzt die Addition. Man setzt den Anfang von B an die Spitze von A.'), ('Summe C: vom *Anfang von A* zur *Spitze von B*', 'Die Summe C geht dann vom Anfang von A bis zur Spitze von B. So entsteht ein Dreieck.'), ('Genauso: *Parallelogramm* aus A und B', 'Dasselbe Ergebnis liefert das Parallelogramm: A und B vom selben Punkt aus antragen, ergänzen, und die Diagonale ist die Summe.'), ('Im Bauwesen: zwei Kräfte → *eine Resultierende*', 'Genau so fasst du in der Statik mehrere Kräfte zu einer Resultierenden zusammen.')]), ('Summe und Differenz', [('Links: c = a + b – Spitze an Anfang', 'Links die Summe: a, dann b an die Spitze von a. Der rote Vektor c geht vom Anfang bis zum Ende.'), ('Rechts: d = a − b = a + (*−b*)', 'Rechts die Differenz. Minus b heißt: b umdrehen und dann addieren. a minus b ist also a plus minus b.'), ('Merke: Subtrahieren = *Gegenvektor addieren*', 'Merke: Einen Vektor abziehen heißt, seinen Gegenvektor addieren.')]), ('Differenz und Vielfache', [('A − B = A + (−B) · A − A = *Nullvektor*', 'Formal steht es hier noch einmal: A minus B ist A plus minus B. Und A minus A ergibt den Nullvektor, mit Betrag null und ohne Richtung.'), ('p · A: Länge *mal p* · p < 0 → Richtung *umgedreht*', 'Ein Vektor mal eine Zahl p: Die Länge wird p-mal so groß. Ist p negativ, dreht sich die Richtung um.'), ('Beispiel: 2a doppelt so lang · −½a halb so lang, entgegengesetzt', 'Zum Beispiel ist zwei a doppelt so lang wie a. Minus ein halb a ist halb so lang und zeigt in die Gegenrichtung.')]), ('Rechengesetze', [('Reihenfolge egal: *A + B = B + A*', 'Für Vektoren gelten die gleichen Rechengesetze wie für Zahlen. Die Reihenfolge der Summanden ist egal.'), ('Klammern verschieben · *ausmultiplizieren* wie gewohnt', 'Klammern darf man verschieben, und ausmultiplizieren funktioniert wie gewohnt. Hier gibt es also nichts Neues zu lernen.')]), ('Einheitsvektoren', [('Einheitsvektor: *Betrag 1* – zeigt nur die Richtung', 'Ein Einheitsvektor hat die Länge eins. Er trägt also nur die Richtung.'), ('Aus jedem Vektor: *a = A / |A|*', 'Aus jedem Vektor bekommst du ihn, indem du den Vektor durch seinen eigenen Betrag teilst.'), ('*i, j, k*: Einheitsvektoren in *x, y, z*', 'Besonders wichtig sind i, j und k. Sie zeigen in Richtung der x-, y- und z-Achse und stehen senkrecht aufeinander.')]), ('Komponenten und Betrag', [('A = A₁ i + A₂ j + A₃ k – *Komponenten*', 'Jeder Vektor lässt sich aus diesen drei Einheitsvektoren zusammensetzen: A eins mal i plus A zwei mal j plus A drei mal k. Die Zahlen A eins bis A drei heißen Komponenten.'), ('Betrag: *|A| = √(A₁² + A₂² + A₃²)* – Pythagoras', 'Der Betrag ist die Wurzel aus der Summe der Quadrate. Das ist der Satz des Pythagoras in drei Dimensionen.'), ('Beispiel A = (2; 3; 6): √(4 + 9 + 36) = √49 = *7*', 'Ein Beispiel: Für A gleich zwei, drei, sechs rechnest du vier plus neun plus sechsunddreißig, das sind neunundvierzig. Die Wurzel daraus ist sieben.')]), ('Komponenten in der Ebene', [('Lot von der Spitze auf die Achsen → *a_x* und *a_y*', 'In der Ebene zerlegt man so: Von der Spitze fällt man das Lot auf die x-Achse und auf die y-Achse.'), ('a = a_x e_x + a_y e_y – *Summe der roten Pfeile*', 'Der Vektor ist dann die Summe der beiden roten Pfeile: a x mal e x plus a y mal e y. Die Zahlen a x und a y sind die Komponenten.'), ('Hier beide *positiv* → erster Quadrant', 'Hier sind beide Komponenten positiv, der Vektor liegt also im ersten Quadranten.')]), ('Der Betrag', [('Betrag = *Länge* – egal in welchem Quadranten', 'Der Betrag ist die Länge des Pfeils. Er ist in jedem Quadranten gleich, egal welche Vorzeichen die Komponenten haben.'), ('*a = √(a_x² + a_y²)* – Quadrate machen alles positiv', 'Gerechnet wird mit Pythagoras. Durch das Quadrieren spielen die Vorzeichen keine Rolle mehr.'), ('Beispiel a = (−3; 4): √(9 + 16) = *5*', 'Zum Beispiel a gleich minus drei und vier: neun plus sechzehn ist fünfundzwanzig, die Wurzel ist fünf. Der Betrag wird ohne Pfeil geschrieben.')]), ('Der Richtungswinkel', [('Winkel φ: von der *positiven x-Achse*, *gegen* den Uhrzeigersinn', 'Die Richtung gibt man mit dem Richtungswinkel phi an. Er wird von der positiven x-Achse aus gegen den Uhrzeigersinn gemessen.'), ('1. Quadrant: *φ = arctan(a_y / a_x)*', 'Im ersten Quadranten gilt einfach: phi gleich Arkustangens von a y durch a x.'), ('Taschenrechner liefert nur −90° … +90° → *Quadrant prüfen*', 'Aber der Taschenrechner liefert nur Winkel zwischen minus neunzig und plus neunzig Grad. Deshalb musst du den Quadranten prüfen.'), ('2. und 3. Quadrant: *+ π (180°)* · 4. Quadrant: *+ 2π (360°)*', 'Im zweiten und dritten Quadranten addierst du pi, also hundertachtzig Grad. Im vierten Quadranten zwei pi, also dreihundertsechzig Grad.'), ('a = (−3; 4): arctan(4/−3) = −53,1° → +180° = *126,9°*', 'Beispiel minus drei und vier: Der Taschenrechner sagt minus dreiundfünfzig Komma eins Grad. Der Vektor liegt aber im zweiten Quadranten, also plus hundertachtzig: hundertsechsundzwanzig Komma neun Grad.')]), ('Sonderfall a_x = 0', [('a_x = 0: Division durch null → *Sonderfall*', 'Ist die x-Komponente null, kann man nicht durch sie teilen. Dann gilt:'), ('a_y > 0 → *φ = π/2 = 90°* · a_y < 0 → *φ = 3π/2 = 270°*', 'Zeigt der Vektor nach oben, ist phi gleich pi halbe, also neunzig Grad. Zeigt er nach unten, ist phi gleich drei pi halbe, also zweihundertsiebzig Grad.')]), ('Einheitsvektor mit cos und sin', [('Einheitsvektor: *e_a = a / a*', 'Den Einheitsvektor in Richtung von a bekommst du, indem du a durch seinen Betrag teilst.'), ('Oder über den Winkel: *e_a = cos φ e_x + sin φ e_y*', 'Er ist auch schon durch den Winkel festgelegt: Seine x-Komponente ist Kosinus phi, seine y-Komponente Sinus phi. Weil Kosinus Quadrat plus Sinus Quadrat eins ist, hat er die Länge eins.'), ('Komponenten: *a_x = a cos φ* · *a_y = a sin φ*', 'Damit gilt für jeden Vektor: a x ist Betrag mal Kosinus phi, a y ist Betrag mal Sinus phi.'), ('Probe: 5 · cos 126,9° = *−3* · 5 · sin 126,9° = *4* ✓', 'Probe mit unserem Beispiel: fünf mal Kosinus hundertsechsundzwanzig Komma neun Grad ist minus drei, fünf mal Sinus ist vier. Passt.')]), ('Vektoren komponentenweise addieren', [('Summe: *x mit x, y mit y* addieren', 'Rechnerisch addiert man Vektoren komponentenweise: die x-Komponenten zusammen und die y-Komponenten zusammen.'), ('c = (a_x + b_x) e_x + (a_y + b_y) e_y', 'Das steht unten links in rot. Beachte: Im Bild ist die x-Komponente von b negativ. Das Vorzeichen wird einfach mitgenommen.'), ('Beispiel: (3; 1) + (−1; 2) = *(2; 3)* · (3; 1) − (−1; 2) = *(4; −1)*', 'Ein Zahlenbeispiel: drei, eins plus minus eins, zwei ergibt zwei, drei. Und die Differenz: drei minus minus eins ist vier, eins minus zwei ist minus eins.')]), ('Vektoren im Raum', [('3D: dazu kommt die *z-Komponente*', 'In drei Dimensionen kommt die z-Achse dazu. Der Vektor hat dann drei Komponenten.'), ('Betrag: *a = √(a_x² + a_y² + a_z²)*', 'Der Betrag ist wieder Pythagoras: die Wurzel aus der Summe der drei Quadrate.'), ('Zweiter Winkel: *θ = arccos(a_z / a)* gegen die z-Achse', 'Für die Richtung braucht man zwei Winkel: phi in der x-y-Ebene, wie bisher, und theta, gemessen von der z-Achse. Theta ist der Arkuskosinus von a z durch a.'), ('Beispiel A = (2; 3; 6): θ = arccos(6/7) ≈ *31°*', 'Für unser Beispiel zwei, drei, sechs mit Betrag sieben ist theta gleich Arkuskosinus von sechs Siebteln, etwa einunddreißig Grad.')]), ('Das Skalarprodukt', [('Skalarprodukt: zwei Vektoren → *eine Zahl*', 'Jetzt die zwei Produkte. Zuerst das Skalarprodukt: Es macht aus zwei Vektoren eine Zahl.'), ('*A · B = A B cos θ* – Beträge mal Kosinus des Winkels', 'Definiert ist es als Betrag von A mal Betrag von B mal Kosinus des eingeschlossenen Winkels theta.'), ('Folie: „Vektorprodukt“ – gemeint ist das *Skalarprodukt*', 'Kleiner Fehler auf der Folie: Dort steht Vektorprodukt. Gemeint ist das Skalarprodukt. Das Vektorprodukt ist etwas anderes und liefert einen Vektor.')]), ('Skalarprodukt: die Kiste auf der Rampe', [('Kiste mit Seil (F) die Rampe hinauf (d)', 'Stell dir vor, du ziehst eine Kiste mit einem Seil eine Rampe hinauf. F ist die Seilkraft, d die Verschiebung entlang der Rampe.'), ('Nur der Anteil *F cos φ* in Richtung d zählt', 'Für die Bewegung zählt nur der Teil der Kraft, der entlang der Rampe zeigt. Den bekommst du mit dem Lot: F mal Kosinus phi, die rote Strecke.'), ('F · d = (F cos φ) · d', 'Das Skalarprodukt ist dieser Anteil mal die Länge von d. Physikalisch ist das die Arbeit.'), ('Mit Komponenten: *F_x d_x + F_y d_y + F_z d_z*', 'Mit Komponenten rechnest du einfach: x mal x plus y mal y plus z mal z.'), ('Beispiel F = (3; 4) N, d = (2; 0) m: 3·2 + 4·0 = *6 N·m*', 'Ein Beispiel: F gleich drei, vier Newton, d gleich zwei, null Meter. Drei mal zwei plus vier mal null ist sechs Newtonmeter. Probe: F ist fünf Newton, Kosinus phi ist drei Fünftel, fünf mal drei Fünftel mal zwei ist auch sechs.')]), ('Wann ist das Skalarprodukt null?', [('*Senkrecht*: cos 90° = 0 → Skalarprodukt *null*', 'Daraus folgen drei wichtige Fälle. Stehen die Vektoren senkrecht aufeinander, ist der Kosinus von neunzig Grad null, also auch das Skalarprodukt.'), ('*Parallel*: maximal · *antiparallel*: minimal (negativ)', 'Sind sie parallel, ist das Skalarprodukt maximal. Sind sie antiparallel, ist es minimal, nämlich negativ, weil der Kosinus von hundertachtzig Grad minus eins ist.'), ('Test: (1; 2) · (2; −1) = 2 − 2 = *0* → senkrecht', 'Das ist ein schneller Test auf senkrecht: eins, zwei mal zwei, minus eins ergibt zwei minus zwei, also null. Die beiden stehen senkrecht.')]), ('Das Vektorprodukt', [('Tür: r vom *Scharnier* zur Klinke, F = Seilkraft', 'Beim Vektorprodukt interessiert das Gegenteil: der senkrechte Anteil. Denk an eine Tür. r zeigt vom Scharnier zur Klinke, F ist die Kraft am Seil.'), ('Drehen kann nur der *senkrechte* Anteil: *r sin φ*', 'Die Tür dreht sich nur durch den Anteil, der senkrecht steht. Das ist r mal Sinus phi.'), ('Betrag: *M = r F sin φ* (Drehmoment)', 'Der Betrag des Vektorprodukts ist also r mal F mal Sinus phi. Das ist das Drehmoment.'), ('Winkel: Folie 0 … π/2 – allgemein 0 … π, Betrag gleich wegen sin φ = sin(π − φ)', 'Auf der Folie steht, der Winkel liegt zwischen null und pi halbe. Allgemein liegt er zwischen null und pi. Für den Betrag ist das egal, denn Sinus phi ist gleich Sinus von pi minus phi.')]), ('Richtung des Vektorprodukts', [('M = r × F steht *senkrecht* auf r und F', 'Das Ergebnis ist ein Vektor, der senkrecht auf beiden steht.'), ('Richtung: *Rechtsschraube* – r auf kürzestem Weg zu F drehen', 'Seine Richtung bestimmst du mit der Schraubenregel: Dreh den ersten Vektor r auf kürzestem Weg zu F. In diese Richtung würde sich eine normale Rechtsschraube bewegen.'), ('Reihenfolge zählt: *F × r = −r × F*', 'Wichtig: Beim Vektorprodukt zählt die Reihenfolge. F kreuz r ist minus r kreuz F.')]), ('Vektorprodukt mit Komponenten', [('Hier: Drehung gegen den Uhrzeigersinn → M zeigt *aus der Ebene* (+z)', 'Im Beispiel muss r gegen den Uhrzeigersinn gedreht werden. Die Rechtsschraube kommt aus der Zeichenebene heraus, also in plus z-Richtung.'), ('In der Ebene: *M_z = r_x F_y − r_y F_x*', 'Für Vektoren in der x-y-Ebene gilt mit Komponenten: M z gleich r x mal F y minus r y mal F x.'), ('Beispiel r = (1; 0) m, F = (0; 10) N: M_z = 1·10 − 0·0 = *10 N·m*', 'Ein Beispiel: r gleich ein Meter in x-Richtung, F gleich zehn Newton in y-Richtung. Eins mal zehn minus null mal null gibt zehn Newtonmeter, positiv, also aus der Ebene heraus.'), ('*Parallel* oder antiparallel → sin 0 = 0 → M = 0', 'Und sind r und F parallel, ist der Sinus null. Dann gibt es kein Drehmoment. Damit ist Vorlesung zwei geschafft.')])]
